import { color } from "../components/color.js";
import { getThemeConfig } from "../internal/theme-state.js";
import { brands } from "./brand.js";
export const brand = brands.purple.primary;
function withStyles(palette, styles) {
    return Object.defineProperty(palette, "styles", {
        value: styles,
        enumerable: false
    });
}
function brandColor(activeBrand, purple) {
    return activeBrand.name === "purple" ? purple : color.hex(activeBrand.primary);
}
function brandBackground(activeBrand, purple) {
    return activeBrand.name === "purple" ? purple : color.bgHex(activeBrand.primary);
}
export function createPalette(activeBrand, mode) {
    const isPurple = activeBrand.name === "purple";
    if (mode === "light") {
        const active = color.hex(activeBrand.primary);
        const prompt = isPurple ? color.hex("#006699") : active;
        const number = isPurple ? color.hex("#0077cc") : active;
        return withStyles({
            header: (text) => active.bold(text),
            divider: (text) => color.hex("#666666")(text),
            prompt: (text) => prompt.bold(text),
            number: (text) => number.bold(text),
            intro: (text) => color.bgHex(activeBrand.primary).white(` ${getThemeConfig().label} - ${text} `),
            get resolvedSymbol() {
                return active("◇");
            },
            get errorSymbol() {
                return color.hex("#cc0000")("■");
            },
            accent: (text) => prompt.bold(text),
            muted: (text) => color.hex("#666666")(text),
            success: (text) => color.hex("#008800")(text),
            warning: (text) => color.hex("#cc6600")(text),
            error: (text) => color.hex("#cc0000")(text),
            info: (text) => active(text),
            badge: (text) => color.bgHex("#cc6600").white(` ${text} `)
        }, {
            accent: { fg: isPurple ? "#006699" : activeBrand.primary, bold: true },
            muted: { fg: "#666666" },
            success: { fg: "#008800" },
            warning: { fg: "#cc6600" },
            error: { fg: "#cc0000" },
            info: { fg: activeBrand.primary }
        });
    }
    const active = brandColor(activeBrand, color.magenta);
    const activeBright = brandColor(activeBrand, color.magentaBright);
    const activeBackground = brandBackground(activeBrand, color.bgMagenta);
    const prompt = isPurple ? color.cyan : active;
    const number = isPurple ? color.cyanBright : active;
    return withStyles({
        header: (text) => activeBright.bold(text),
        divider: (text) => color.dim(text),
        prompt: (text) => prompt(text),
        number: (text) => number(text),
        intro: (text) => activeBackground.white(` ${getThemeConfig().label} - ${text} `),
        get resolvedSymbol() {
            return active("◇");
        },
        get errorSymbol() {
            return color.red("■");
        },
        accent: (text) => prompt(text),
        muted: (text) => color.dim(text),
        success: (text) => color.green(text),
        warning: (text) => color.yellow(text),
        error: (text) => color.red(text),
        info: (text) => active(text),
        badge: (text) => color.bgYellow.black(` ${text} `)
    }, {
        accent: { fg: isPurple ? "cyan" : activeBrand.primary, bold: true },
        muted: { dim: true },
        success: { fg: "green" },
        warning: { fg: "yellow" },
        error: { fg: "red" },
        info: { fg: isPurple ? "magenta" : activeBrand.primary }
    });
}
export const dark = createPalette(brands.purple, "dark");
export const light = createPalette(brands.purple, "light");
